// 1. GÜVENLİK FİLTRESİ
if (!msg.payload || typeof msg.payload !== 'object' || !msg.payload.makine) {
    return null;
}

let hamMakine = msg.payload.makine || msg.topic || "";
let presMatch = String(hamMakine).match(/pres\s*([0-9]+)/i);
if (!presMatch && msg.topic) {
    presMatch = String(msg.topic).match(/pres\s*([0-9]+)/i);
}
if (!presMatch) {
    node.status({ fill: "red", shape: "ring", text: "Pres no bulunamadı: " + hamMakine });
    return null;
}

let presNo = presMatch[1];
let makineAdi = "Pres " + presNo;

let yeniKalip = String(msg.payload.kalip_adi || msg.payload.kalip || "SEÇİLMEDİ").trim();
if (!yeniKalip || yeniKalip === "-" || yeniKalip.toUpperCase() === "SECILMEDI") {
    yeniKalip = "SEÇİLMEDİ";
}

let vurus = Number(msg.payload.toplam_uretim) || 0;
let makineDurumu = String(msg.payload.makine_durumu ?? "0").trim().toUpperCase();
if (makineDurumu === "CALISIYOR") makineDurumu = "ÇALIŞIYOR";

// 2. KALIP VERİTABANI
const veritabani = {
    "DW-013": 1, "DW-012": 1, "DW-016": 1, "DW-015": 1, "DW-015A": 1,
    "DW-011A": 1, "DW-005": 1, "DW-008": 1, "DW-007": 1, "DW-001": 1,
    "DW-002": 1, "DW-003": 1, "DW-006": 1, "DW-014": 1, "DW-011": 1,
    "DW-009": 1, "DW-010": 1,
    "YEŞİL KALIP-3 GÖZLÜ": 1, "MAVİ KALIP-4 GÖZLÜ": 1,
    "YEŞİL KALIP-2 GÖZLÜ": 1, "MAVİ KALIP-2 GÖZLÜ": 1,
    "YEŞİL KALIP-4 GÖZLÜ": 1, "YEŞİL KALIP-1 GÖZLÜ": 1,
    "MAVİ KALIP-3 GÖZLÜ": 1, "DW-LAM": 1,
    "YTD-01": 1, "YTDE-01": 1, "YTSD-01": 1,
    "YTB-01": 1, "YTM-01": 1, "YTÇ-01": 1, "YTH2-01": 1
};

// 3. SESSION ÇEK
let suAn = new Date().toLocaleTimeString('tr-TR', { hour: '2-digit', minute: '2-digit' });
let bugun = new Date().toLocaleDateString('tr-TR');

let session = flow.get('session_pres_' + presNo) || {
    kalip: yeniKalip,
    baslangic_vurus: vurus,
    baslangic_saat: suAn
};

let raporGuncellendi = false;
let raporListesi = global.get('merkezi_haftalik_rapor') || [];

let urunSecimi = String(msg.payload.urun || msg.payload.urun_adi || "").trim();
let operatorSecimi = String(msg.payload.operator || "").trim();

function bosSecimMi(v) {
    let s = String(v ?? "").trim().toUpperCase();
    return (!s || s === "-" || s === "SEÇİLMEDİ" || s === "SECILMEDI" || s === "BİLİNMİYOR" || s === "BILINMIYOR");
}

// 4. KALIP DEĞİŞİMİ TESPİTİ
if (session.kalip !== yeniKalip) {

    if (
        session.kalip !== "SEÇİLMEDİ" &&
        session.kalip !== "-" &&
        !bosSecimMi(session.kalip) &&
        !bosSecimMi(urunSecimi) &&
        !bosSecimMi(operatorSecimi)
    ) {
        let netVurus = vurus - session.baslangic_vurus;
        if (netVurus < 0) {
            // Sayaç sıfırlanmış, bu oturumu iptal et
            session.baslangic_vurus = 0;
            flow.set('session_pres_' + presNo, session);
            netVurus = 0;
        }

        let carpan = veritabani[session.kalip] || 1;
        let uretimMiktari = netVurus * carpan;

        if (uretimMiktari > 0) {
        raporListesi.push({
    gun: bugun,
    pres: makineAdi,
    operator: operatorSecimi,
    urun: urunSecimi,
    kalip: session.kalip,
    baslangic: session.baslangic_vurus * carpan,
    bitis: vurus * carpan,
    net: uretimMiktari,
    b_saat: session.baslangic_saat,
    bitis_saat: suAn,
    vardiya: (function(){
        var parts = session.baslangic_saat ? session.baslangic_saat.split(":") : [];
        var dk = parts.length >= 2 ? parseInt(parts[0])*60 + parseInt(parts[1]) : -1;
        return (dk >= 475 && dk < 1110) ? "Sabah" : "Aksam";
    })(),
    durus: msg.payload.durus_suresi || "00:00"
});
            if (raporListesi.length > 500) raporListesi.shift();
            global.set('merkezi_haftalik_rapor', raporListesi);
            raporGuncellendi = true;
        }
    }

    // Yeni kalıp için birikimli başlangıcı kaydet
    let ko = global.get('kalipOmurleri') || {};
    let yd = ko[yeniKalip] || { toplamVurus: 0 };
    yd.oncekiBirikimli = yd.toplamVurus || 0;
    ko[yeniKalip] = yd;
    global.set('kalipOmurleri', ko);

    // Yeni session başlat
   session = {
    kalip: yeniKalip,
    baslangic_vurus: vurus < 0 ? 0 : vurus,
    baslangic_saat: suAn
};
    flow.set('session_pres_' + presNo, session);
}

// 5. HAFIZA YÖNETİMİ
let temizlemeKilidi = global.get("temizlemeKilidi_pres" + presNo);
if (temizlemeKilidi === true && yeniKalip !== "SEÇİLMEDİ") {
    node.status({ fill: "yellow", shape: "ring", text: makineAdi + " temiz modda - eski kalıp engellendi" });
    global.set("aktifKalip_pres" + presNo, "SEÇİLMEDİ");
    return [null, null];
}

let aktifHafiza = global.get('aktifKalip_pres' + presNo);
if (aktifHafiza !== yeniKalip) {
    if (yeniKalip !== "SEÇİLMEDİ" && yeniKalip !== "-") {
        for (let i = 1; i <= 14; i++) {
            if (i.toString() !== presNo && global.get('aktifKalip_pres' + i) === yeniKalip) {
                global.set('aktifKalip_pres' + i, "SEÇİLMEDİ");
                global.set("temizlemeKilidi_pres" + i, true);
            }
        }
    }

}

// 6. ANLIK KALIP ÖMÜR GÜNCELLE
if (yeniKalip !== "SEÇİLMEDİ" && yeniKalip !== "-") {
    let kalipOmurleri = global.get('kalipOmurleri') || {};
    let kalipData = kalipOmurleri[yeniKalip] || { toplamVurus: 0, oncekiBirikimli: 0 };

    let netVurus = vurus - session.baslangic_vurus;

    // Eksi gelirse session'ı sıfırla (pres veya kalıp sıfırlandı)
    if (netVurus < 0) {
        netVurus = 0;
        session.baslangic_vurus = vurus;
        flow.set('session_pres_' + presNo, session);
    }

    let carpan = veritabani[yeniKalip] || 1;
    kalipData.toplamVurus = (kalipData.oncekiBirikimli || 0) + (netVurus * carpan);

    kalipOmurleri[yeniKalip] = kalipData;
    global.set('kalipOmurleri', kalipOmurleri);
}

// Her mesajda ürün ve kalıp güncelle
global.set('aktifKalip_pres' + presNo, yeniKalip);
let urunAdi = String(msg.payload.urun_adi || msg.payload.urun || '—').trim();
if (urunAdi && urunAdi !== '—') {
    global.set('aktifUrun_pres' + presNo, urunAdi);
}

let kalipBilgi = global.get('kalipBilgi') || {};
// Eski kalıbı temizle
for (let k in kalipBilgi) {
    if (kalipBilgi[k].pres === makineAdi) delete kalipBilgi[k];
}
// Yeni kalıbı ekle
if (yeniKalip !== 'SEÇİLMEDİ') {
    kalipBilgi[yeniKalip] = { pres: makineAdi, atanmaTarihi: new Date().toISOString() };
}
global.set('kalipBilgi', kalipBilgi);

// 7. DURUM
global.set('durum_pres' + presNo, makineDurumu);

let calisiyorMu = (
    makineDurumu === "1" ||
    makineDurumu === "ÇALIŞIYOR" ||
    makineDurumu === "AKTİF" ||
    makineDurumu === "AKTIF"
);

node.status({
    fill: calisiyorMu ? "green" : "grey",
    shape: "dot",
    text: makineAdi + " | " + yeniKalip + " | " + (calisiyorMu ? "AKTİF" : "TAKILI")
});

// 8. ÇIKIŞ
if (raporGuncellendi) {
    return [msg, { payload: raporListesi }];
}
// ========================================================
// 📊 VARDİYA BAZLI & AKTİF/PASİF DURUMLU EXCEL ENTEGRASYONU
// ========================================================
if (raporGuncellendi) {
    let carpan = veritabani[session.kalip] || 1;
    let netVurus = vurus - session.baslangic_vurus;
    if (netVurus < 0) netVurus = 0;
    let uretimMiktari = netVurus * carpan;

    // ⏰ TAM SENİN İSTEDİĞİN VARDİYA SAAT HESABI (07:55 - 18:30)
    let vardiyaYazi = (function () {
        if (!session.baslangic_saat) return "SABAH";
        var parts = session.baslangic_saat.split(":");
        if (parts.length < 2) return "SABAH";

        // Saati gece yarısından itibaren toplam dakikaya çeviriyoruz
        var toplamDakika = parseInt(parts[0], 10) * 60 + parseInt(parts[1], 10);

        var sabahBaslangic = 7 * 60 + 55; // 07:55 = 475. dakika
        var aksamBaslangic = 18 * 60 + 30; // 18:30 = 1110. dakika

        // 07:55 ile 18:30 arası SABAH, geri kalan tüm zamanlar AKŞAM
        if (toplamDakika >= sabahBaslangic && toplamDakika < aksamBaslangic) {
            return "SABAH";
        } else {
            return "AKŞAM";
        }
    })();

    // 🟢 / 🔴 ANLIK DURUMUN AKTİF VEYA PASİF OLARAK YAZILMASI
    let anlikDurumYazi = (
        makineDurumu === "1" ||
        makineDurumu === "ÇALIŞIYOR" ||
        makineDurumu === "AKTİF" ||
        makineDurumu === "AKTIF"
    ) ? "AKTİF" : "PASİF";

    // Google Sheets'in (A, B, C...) sırayla beklediği yeni net özet şablonu
    let googleRaporPayload = {
        row: [
            bugun,                                // A: TARİH
            makineAdi.toUpperCase(),              // B: PRES ADI
            operatorSecimi.toUpperCase(),         // C: OPERATÖR
            session.kalip.toUpperCase(),          // D: KALIP NO
            urunSecimi.toUpperCase(),             // E: ÜRETİLEN ÜRÜN
            session.baslangic_vurus * carpan,     // F: BAŞLANGIÇ DEĞERİ
            vurus * carpan,                       // G: BİTİŞ DEĞERİ
            uretimMiktari,                        // H: NET ÜRETİM
            vardiyaYazi,                          // I: VARDİYA (SABAH / AKŞAM)
            anlikDurumYazi                        // J: ANLIK DURUM (AKTİF / PASİF)
        ]
    };

    // 1. Çıkış (Boş) | 2. Çıkış: Sadece tetiklendiğinde HTTP Request düğümüne gider
    msg.payload = googleRaporPayload;
    return [null, msg];
}

// Rapor tetiklenmediyse hiçbir yere istek atma, Excel'i şişirme
return [null, null];

let raporListesi = global.get('merkezi_haftalik_rapor') || [];

function bosDegerMi(v) {
    let s = String(v ?? "").trim().toUpperCase();

    return (
        !s ||
        s === "-" ||
        s === "SEÇİLMEDİ" ||
        s === "SECILMEDI" ||
        s === "BİLİNMİYOR" ||
        s === "BILINMIYOR"
    );
}

// Eğer payload array geldiyse, bunu tekrar listeye ekleme.
// Sadece tabloyu yenile.
if (Array.isArray(msg.payload)) {
    raporListesi = msg.payload;
} else if (msg.payload && typeof msg.payload === "object") {

    let satir = msg.payload;

    // Kalıp / ürün / pres eksikse rapora alma
    if (
        bosDegerMi(satir.pres) ||
        bosDegerMi(satir.urun) ||
        bosDegerMi(satir.operator)
    ) {
        node.status({
            fill: "yellow",
            shape: "ring",
            text: "Eksik seçimli kayıt rapora alınmadı"
        });

        msg.payload = raporListesi;
        return msg;
    }

    // Net üretim yoksa alma
if ((Number(satir.net) || 0) < 0) 
{
            msg.payload = raporListesi;
        return msg;
    }

    raporListesi.push(satir);
}

// Bozuk satırları temizle
raporListesi = raporListesi.filter(satir => {
    if (!satir || Array.isArray(satir) || typeof satir !== "object") return false;

    if (bosDegerMi(satir.gun)) return false;
    if (bosDegerMi(satir.pres)) return false;
    if (bosDegerMi(satir.urun)) return false;
    if (bosDegerMi(satir.operator)) return false;
    if ((Number(satir.net) || 0) <= 0) return false;

    return true;
});

// Son 500 kayıt
if (raporListesi.length > 500) {
    raporListesi = raporListesi.slice(-500);
}

// Pres numarasına göre sırala
raporListesi.sort((a, b) => {
    let nA = parseInt(String(a.pres).match(/\d+/)) || 0;
    let nB = parseInt(String(b.pres).match(/\d+/)) || 0;
    return nA - nB;
});

global.set('merkezi_haftalik_rapor', raporListesi);

msg.payload = raporListesi;
return msg;

// Kalıp ömrü artık Merkezi Kalıp Eşitleyici tarafından hesaplanıyor
// Bu fonksiyon devre dışı bırakıldı - çift sayımı önlemek için
return msg;

let tumKalipler = [
    { isim: "DW-001", limit: 50000 }, { isim: "DW-002", limit: 75000 },
    { isim: "DW-003", limit: 30000 }, { isim: "DW-005", limit: 50000 },
    { isim: "DW-006", limit: 100000 }, { isim: "DW-007", limit: 50000 },
    { isim: "DW-008", limit: 50000 }, { isim: "DW-009", limit: 50000 },
