    { isim: "DW-011A", limit: 45000 }, { isim: "DW-012", limit: 50000 },
    { isim: "DW-013", limit: 50000 }, { isim: "DW-014", limit: 50000 },
    { isim: "DW-015", limit: 50000 }, { isim: "DW-015A", limit: 50000 },
    { isim: "YEŞİL KALIP-1 GÖZLÜ", limit: 25000 }, { isim: "YEŞİL KALIP-2 GÖZLÜ", limit: 25000 },
    { isim: "YEŞİL KALIP-3 GÖZLÜ", limit: 25000 }, { isim: "YEŞİL KALIP-4 GÖZLÜ", limit: 25000 },
    { isim: "MAVİ KALIP-2 GÖZLÜ", limit: 35000 }, { isim: "MAVİ KALIP-3 GÖZLÜ", limit: 35000 },
    { isim: "MAVİ KALIP-4 GÖZLÜ", limit: 35000 }, { isim: "YTD-01", limit: 50000 },
