    { isim: "DW-LAM", limit: 50000 }

];

let kalipOmurleri = global.get('kalipOmurleri') || {};
let suAnkiAtamalar = {};

function bosKalipMi(kalip) {
    let k = String(kalip || "").trim().toUpperCase();

    return (
        !k ||
        k === "-" ||
        k === "SEÇİLMEDİ" ||
        k === "SECILMEDI"
    );
}

function durumEtiketi(durum) {
    let d = String(durum || "").trim().toUpperCase();

    if (
        d === "1" ||
        d === "ÇALIŞIYOR" ||
        d === "CALISIYOR" ||
        d === "AKTİF" ||
        d === "AKTIF"
    ) {
        return "AKTİF";
    }

    return "TAKILI";
}

// Hangi pres üzerinde hangi kalıp var, merkezi hafızadan oku
for (let i = 1; i <= 14; i++) {
    let aktifK = global.get('aktifKalip_pres' + i);
    let pDurum = global.get('durum_pres' + i);

    if (!bosKalipMi(aktifK)) {
        suAnkiAtamalar[String(aktifK).trim()] = {
            pres: "Pres " + i,
            durum: durumEtiketi(pDurum)
        };
    }
}

let tablo = tumKalipler.map(item => {
    let k = item.isim;
    let data = kalipOmurleri[k] || { toplamVurus: 0, limit: item.limit };
    let vurus = data.toplamVurus || 0;
    let limit = data.limit || item.limit;
    let oran = Math.min(Math.round((vurus / limit) * 100), 100);

    let barRengi = (oran > 85) ? "#e53e3e" : (oran > 65 ? "#ed8936" : "#38a169");

    let durum = "PASİF";
    let pres = "-";

    // Eğer kalıp doluysa (suAnkiAtamalar'da eşleştiyse) bilgilerini bas
    if (suAnkiAtamalar[k]) {
        pres = suAnkiAtamalar[k].pres;
        durum = suAnkiAtamalar[k].durum;
    }

    return {
        "kalipNo": k,
        "vurus": vurus,
        "limit": limit,
        "oran": oran,
        "barRengi": barRengi,
        "durum": durum,
        "pres": pres
    };
});

msg.payload = tablo;
return msg;

// Sadece tablo tıklamasını (topic: secilen) kabul et
if (msg.topic !== "secilen") return null;

return msg;

let komut = msg.topic;
let kalipNo = msg.payload.kalipNo;
let makineAdi = msg.payload.makine; 

let kalipOmurleri = global.get('kalipOmurleri') || {};

// DURUM 1 & 2: Ana Pi Hafıza Güncellemeleri
if (komut === "limit_guncelle" || komut === "kalip_sifirla") {
    if (kalipOmurleri[kalipNo]) {
        if (komut === "limit_guncelle") kalipOmurleri[kalipNo].limit = parseInt(msg.payload.limit);
        if (komut === "kalip_sifirla") kalipOmurleri[kalipNo].toplamVurus = 0;
        global.set('kalipOmurleri', kalipOmurleri);
    }
    node.status({ fill: "green", shape: "dot", text: kalipNo + " güncellendi" });
    return [msg, null]; // Sadece 1. çıkışa (üst) gönder
}

// DURUM 3: Pres Sayacı Sıfırlama (Yerel Pi'ye Gidecek)
if (komut === "pres_sifirla" && makineAdi) {
    let presNo = makineAdi.replace("Pres ", "").trim();

    msg.topic = "fabrika/pres" + presNo + "/komut";
    msg.payload = { komut: "reset_pres_sayaci" };

    node.status({ fill: "red", shape: "dot", text: makineAdi + " RESET gönderildi" });

    // DİKKAT: Burada [null, msg] diyerek mesajı 2. çıkışa (alt yola) yönlendiriyoruz
    return [null, msg]; 
}

return null;

let liste = global.get('merkezi_haftalik_rapor') || [];
let bugun = new Date().toLocaleDateString('tr-TR');
let urunToplam = {};

// Debug: Hafızada kaç kayıt var?
// node.warn("Toplam Kayıt Sayısı: " + liste.length);

let bugunKayitlari = liste.filter(item => {
    // Tarih uyuşmazlığını önlemek için boşlukları temizle
    return String(item.gun).trim() === String(bugun).trim();
});

bugunKayitlari.forEach(item => {
    // Alternatif anahtar isimlerini kontrol et
    let urunAdi = item.urun || item.urun_adi || "Tanımsız Ürün";
    let adet = parseInt(item.net) || 0;

    if (!urunToplam[urunAdi]) {
        urunToplam[urunAdi] = 0;
    }
    urunToplam[urunAdi] += adet;
});

let sonucArray = Object.keys(urunToplam).map(urun => {
    return { urun: urun, toplam: urunToplam[urun] };
});

sonucArray.sort((a, b) => b.toplam - a.toplam);

if (sonucArray.length === 0) {
    sonucArray.push({ urun: "Bugün (" + bugun + ") henüz üretim yok", toplam: 0 });
}

msg.payload = sonucArray;
return msg;

// 1. BURAYA GRUP ID'Nİ YAZ
// Eksi (-) işaretini unutma!
let patronGrubuID = -1003801756063; // <--- KENDI NUMARANLA DEĞİŞTİR

let bugun = new Date().toLocaleDateString('tr-TR');
let liste = global.get('merkezi_haftalik_rapor') || [];

// 2. Bugünün verilerini filtrele
let bugunKayitlari = liste.filter(item => String(item.gun).trim() === String(bugun).trim());

if (bugunKayitlari.length === 0) {
    return null; // Bugün üretim yoksa mesaj atma
}

let urunToplam = {};
let genelToplam = 0;

bugunKayitlari.forEach(item => {
    let urunAdi = item.urun || "Belirtilmeyen Ürün";
    let adet = parseInt(item.net) || 0;

    if (!urunToplam[urunAdi]) urunToplam[urunAdi] = 0;
    urunToplam[urunAdi] += adet;
    genelToplam += adet;
});

// 3. Şık Mesaj Şablonu
let mesaj = "🏭 GÜNLÜK ÜRETİM RAPORU\n";
mesaj += "📅 Tarih: " + bugun + "\n";
mesaj += "━━━━━━━━━━━━━━━━━━━━\n\n";

for (let urun in urunToplam) {
    mesaj += "📦 " + urun + " = " + urunToplam[urun].toLocaleString('tr-TR') + " Adet\n";
}

mesaj += "\n━━━━━━━━━━━━━━━━━━━━\n";
mesaj += "🤖 Sistem tarafından otomatik gönderilmiştir.";

// 4. Gönderim Paketi
msg.payload = {
    chatId: -1003801756063,
    type: "message",
    content: mesaj,
    parse_mode: "Markdown"
};

return msg;

let presNo = Number(msg.payload);

if (!presNo || presNo < 1 || presNo > 14) {
    node.status({
        fill: "red",
        shape: "ring",
        text: "Geçersiz pres no"
    });
    return null;
}

// 1) Merkez hafızada bu presin aktif kalıbını temizle
global.set("aktifKalip_pres" + presNo, "SEÇİLMEDİ");
global.set("temizlemeKilidi_pres" + presNo, true);

// 2) Session bilgisini temizle
flow.set("session_pres_" + presNo, {
    kalip: "SEÇİLMEDİ",
    baslangic_vurus: 0,
    baslangic_saat: new Date().toLocaleTimeString("tr-TR", {
        hour: "2-digit",
        minute: "2-digit"
    })
});

// 3) Yerel Pi'ye temizlik komutu gönder
let mqttMsg = {
    topic: "fabrika/pres" + presNo + "/ayar",
    payload: {
        komut: "secimleri_temizle",
        kalip: "SEÇİLMEDİ",
        urun: "",
        operator: ""
    }
};

// 4) Genel kalıplar listesini anında yenile
let listeYenileMsg = {
    topic: "kalip_listesi_yenile",
    payload: {
        presNo: presNo,
        islem: "secim_temizle"
    }
};

node.status({
    fill: "green",
    shape: "dot",
    text: "Pres " + presNo + " seçimleri temizlendi"
});

let dropdownTemizleMsg = {
    topic: "dropdown_temizle",
    payload: {
        presNo: presNo
    }
};

let bildirimMsg = {
    topic: "Seçim Temizlendi",
    payload: "Pres " + presNo + " için kalıp, ürün ve operatör temizlendi."

};

return [mqttMsg, listeYenileMsg, dropdownTemizleMsg, bildirimMsg];

if (msg.topic === 'popup_ac') {
    return null;
}

if (msg.topic === 'ariza_baslat') {
    let d = msg.payload;
    if (d.tip === 'rulo') {
        let gecmis = global.get('usta_gecmis') || [];
        gecmis.unshift({
            pres: 'Pres ' + d.presNo,
            kalip: d.kalip || '—',
            tip: 'rulo',
             operator: d.operator || '—',
            tarih: new Date().toLocaleDateString('tr-TR'),
            baslangicSaat: d.baslangicSaat || new Date().toLocaleTimeString('tr-TR', { hour: '2-digit', minute: '2-digit' }),
            bitisSaat: d.bitisSaat || '—',
            arizaSure: d.arizaSure || '—',
            mudahaleSure: '—',
            parca: '', not: ''
        });
        if (gecmis.length > 100) gecmis.pop();
        global.set('usta_gecmis', gecmis);
        msg.topic = 'gecmis_guncelle';
        msg.payload = gecmis;
        return msg;
    }
    let aktifArizalar = global.get('aktif_arizalar') || [];
    let yeniAriza = {
        id: Date.now(),
        pres: 'Pres ' + d.presNo,
        kalip: d.kalip || '—',
        urun: d.urun || '—',
        operator: d.operator || '—',        
        tip: d.tip,
        zaman: new Date().toLocaleTimeString('tr-TR', { hour: '2-digit', minute: '2-digit' }),
        arizaBaslangicMs: Date.now(),
        mudahaleBaslangicMs: null
    };
    aktifArizalar.push(yeniAriza);
    global.set('aktif_arizalar', aktifArizalar);
    msg.topic = 'aktif_arizalar';
    msg.payload = aktifArizalar;
    return msg;
}

if (msg.topic === 'mudahale_baslat') {
    let id = msg.payload.id;
    let aktifArizalar = global.get('aktif_arizalar') || [];
    for (let i = 0; i < aktifArizalar.length; i++) {
        if (aktifArizalar[i].id === id) {
            aktifArizalar[i].mudahaleBaslangicMs = Date.now();
            break;
        }
    }
    global.set('aktif_arizalar', aktifArizalar);
    msg.topic = 'aktif_arizalar';
    msg.payload = aktifArizalar;
    return msg;
}

if (msg.topic === 'mudahale_onay') {
    let id = msg.payload.id;
    let aktifArizalar = global.get('aktif_arizalar') || [];
    aktifArizalar = aktifArizalar.filter(function (a) { return a.id !== id; });
    global.set('aktif_arizalar', aktifArizalar);
    let gecmis = global.get('usta_gecmis') || [];
    gecmis.unshift(msg.payload);
    if (gecmis.length > 100) gecmis.pop();
    global.set('usta_gecmis', gecmis);
    node.send({ topic: 'gecmis_guncelle', payload: gecmis });
    return null;
}

if (msg.topic === 'temizle') {
    global.set('aktif_arizalar', []);
    msg.topic = 'aktif_arizalar';
    msg.payload = [];
    return msg;
}

return null;

if (msg.topic && msg.topic.includes('/')) {
    let topicParcalari = msg.topic.split('/');
    let makineIsmi = topicParcalari[1].toUpperCase();

    msg.payload = {
        makine: makineIsmi,
        makine_durumu: msg.payload.makine_durumu,
        sure: msg.payload.durus_suresi || 0
    };
    return msg;
}
// Eğer gelen mesaj Inject düğmesinden ise (Kalp Atışı), parçalamadan ilet
return msg;

// Hafıza (context) üzerinden durumu takip et (Zıplamayı önler)
var sonDurumlar = context.get('sonDurumlar') || {};

if (msg.payload && msg.topic) {
    // 1. İsim Temizleme (fabrikam/pres1/status -> Pres 1)
    var parcalar = msg.topic.split('/');
    var presID = (parcalar[1] || "").toUpperCase();
    var temizIsim = presID.replace("PRES", "Pres ");

    var anlikDurum = String(msg.payload.makine_durumu).toUpperCase().trim();
    if (anlikDurum === "1") anlikDurum = "ÇALIŞIYOR";
    if (anlikDurum === "0") anlikDurum = "DURDU";

    // 2. SADECE DURUM DEĞİŞTİYSE İŞLEM YAP
    if (anlikDurum !== sonDurumlar[presID]) {
        sonDurumlar[presID] = anlikDurum;
        context.set('sonDurumlar', sonDurumlar);

        // BİLDİRİM BAŞLIĞI: Artık sadece "Pres 1" yazacak
        msg.topic = temizIsim;

        if (anlikDurum === "DURDU") {
            msg.payload = "🚨 DURDU! Müdahale ediniz.";
            msg.highlight = "red";
            return msg;
        }
        else if (anlikDurum === "ÇALIŞIYOR") {
            msg.payload = "✅ ÇALIŞIYOR.";
            msg.highlight = "green";
            return msg;
        }
    }
}
return null;
